#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, limit;
    cin >> n >> limit;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    int left = 0, answer = 0;
    long long sum = 0;
    for (int right = 0; right < n; ++right) {
        sum += a[right];
        while (left <= right && sum > limit) {
            sum -= a[left];
            ++left;
        }
        answer = max(answer, right - left + 1);
    }
    cout << answer << '\n';
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n, x;
    cin >> n >> x;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    sort(a.begin(), a.end());

    int i = 0, j = n - 1;
    while (i < j) {
        int sum = a[i] + a[j];
        if (sum == x) {
            cout << a[i] << ' ' << a[j] << '\n';
            return 0;
        }
        if (sum < x) ++i;
        else --j;
    }
    cout << "NO\n";
    return 0;
}
